# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: per-character player rankings, downloaded by hand about once a month as a zip of CSV
#          files and read straight from the zip (nothing unpacked) into
#          pkgs/ds/data/parquet/char_ranking.parquet with this repo's character ids.
# Usage: `ds data char_ranking [ZIP]` (default: the newest zip in ~/Downloads).
#        How the data is gathered: README.md next to this file.
# ---------------------------------------------------------------------------
#
# Source notes (from the November 2026 release):
# - The zip holds one folder named after the month, eg "November 2026/", with one CSV per
#   ranking: "<name> ranking.csv" (83 of them). The release is dated by that month's last day.
# - Columns: rank, tag, rating, country, id, Is solo main. `id` is the start.gg player id
#   (Sparg0 = 158026), so it joins to ds.data.startgg. `rating` is display text: "10.1k",
#   "1,258", "757.5", "3.787" (k = thousands, ',' groups digits), so big ratings are rounded.
#   It is the player's overall rating, not per character: a player has the same one in every
#   ranking (all 2297 players in 2+ rankings), and each ranking orders its players by it.
# - Rankings cover every ranked player of a character, not just a top 100 (Cloud: 931).
# - Names mostly match our picks by name; the rest are in SITE_RANKING (echo pairs ranked
#   together, a full name, Random).
#
# TODO: archive each downloaded zip in an S3-style bucket (eg Cloudflare R2, where the docs
#   site's assets already live; ds.util.r2 is only a stub so far). That would keep every raw
#   release as history (re-load or re-parse any month on any machine, not just from a zip still
#   in ~/Downloads), and lets the load be automated further, eg a SmashGPT widget that takes
#   the zip, archives it and loads it.
from __future__ import annotations

import datetime as dt
import zipfile
from pathlib import Path, PurePosixPath

import polars as pl

from ds.data.char_icons import char_group_by_name
from ds.data.chars import CharGroup

__all__ = [
    "CHAR_GROUP_DTYPE",
    "COLUMNS",
    "DOWNLOADS_DIR",
    "SITE_RANKING",
    "find_zip",
    "merge_release",
    "month_end",
    "parse_rating",
    "read_release",
    "release_month",
    "unmatched_rankings",
]

# where the browser saves the Drive download (a zip)
DOWNLOADS_DIR = Path.home() / "Downloads"
CHAR_GROUP_DTYPE = pl.Enum([group.value for group in CharGroup])
# a CSV's name is "<ranking> ranking.csv"
_FILE_SUFFIX = " ranking"
# the source's columns -> ours (a different set means the format changed: read_release stops)
COLUMNS = {
    "rank": "rank",
    "tag": "tag",
    "rating": "rating",
    "country": "country",
    "id": "player_id",
    "Is solo main": "is_solo_main",
}

# Rankings whose name doesn't match a pick (ds.data.char_group_by_name): name -> its picks.
# NOTE: echo fighters ranked together (Peach-Daisy, ...) go to every member: each row is stored
# once per member (a Peach-Daisy row as peach and as daisy), with `ranking` saying it was
# combined. The simplest shape for now (char_group_id == 'daisy' just works); revisit if the
# duplicates get in the way (eg counting players across characters).
SITE_RANKING: dict[str, tuple[str, ...]] = {
    "Peach-Daisy": ("peach", "daisy"),
    "Pit-Dark Pit": ("pit", "dark_pit"),
    "Samus-Dark Samus": ("samus", "dark_samus"),
    "Belmont": ("simon", "richter"),
    "Kazuya Mishima": ("kazuya",),
    "Random": (),  # not a character: kept, with a null char_group_id
}


def month_end(day: dt.date) -> dt.date:
    """The last day of `day`'s month, eg 2026-02-28 for 2026-02-10"""
    first_of_next = (day.replace(day=28) + dt.timedelta(days=4)).replace(day=1)
    return first_of_next - dt.timedelta(days=1)


def find_zip(name: str | None = None, downloads: Path | None = None) -> Path:
    """The release's zip: `name` as a path, else a file name in the downloads folder; with no
    name, the newest .zip there. Raises FileNotFoundError saying where it looked.
    """
    folder = downloads or DOWNLOADS_DIR
    if name:
        given = Path(name.strip()).expanduser()
        for path in (given, folder / given):
            if path.is_file():
                return path
        raise FileNotFoundError(f"No file {name!r} (nor in {folder})")
    zips = sorted(folder.glob("*.zip"), key=lambda p: p.stat().st_mtime, reverse=True)
    if not zips:
        raise FileNotFoundError(f"No .zip files in {folder}")
    return zips[0]


def _entry_parts(entry: zipfile.ZipInfo) -> tuple[str, ...]:
    """A zip entry's path as parts (a backslash is a separator too, as in Windows zips)"""
    return PurePosixPath(entry.filename.replace("\\", "/")).parts


def _csv_entries(archive: zipfile.ZipFile) -> list[zipfile.ZipInfo]:
    return [e for e in archive.infolist() if not e.is_dir() and e.filename.lower().endswith(".csv")]


def release_month(zip_path: Path) -> tuple[str, dt.date]:
    """(the zip's folder name, the release date it stands for): the zip holds one folder named
    after the month, eg 'November 2026' -> 2026-11-30 (the month's last day; releases are
    always dated by calendar month end).

    A ValueError when the zip has no CSV files, more than one folder, or a folder name that
    isn't '<Month> <YYYY>'.
    """
    with zipfile.ZipFile(zip_path) as archive:
        tops = {_entry_parts(e)[0] for e in _csv_entries(archive) if len(_entry_parts(e)) > 1}
        if not _csv_entries(archive):
            raise ValueError(f"No .csv files in {zip_path.name}")
    if len(tops) != 1:
        raise ValueError(f"{zip_path.name} should hold one month folder (eg 'November 2026'), found: {sorted(tops)}")
    (folder,) = tops
    try:
        first = dt.datetime.strptime(folder.strip(), "%B %Y").date()  # a month
    except ValueError:
        raise ValueError(f"{zip_path.name}'s folder {folder!r} isn't a month like 'November 2026'") from None
    return folder, month_end(first)


def parse_rating(text: pl.Expr) -> pl.Expr:
    """The source's display rating as a number: '10.1k' -> 10100, '1,258' -> 1258"""
    clean = text.str.strip_chars().str.replace_all(",", "")
    thousands = clean.str.to_lowercase().str.ends_with("k")
    number = clean.str.strip_chars_end("kK").cast(pl.Float64)
    return pl.when(thousands).then(number * 1000).otherwise(number)


def _ranking_name(entry: zipfile.ZipInfo) -> str:
    """'November 2026/Peach-Daisy ranking.csv' -> 'Peach-Daisy'"""
    return PurePosixPath(_entry_parts(entry)[-1]).stem.removesuffix(_FILE_SUFFIX).strip()


def _groups(ranking: str) -> list[str]:
    """The picks a ranking is about: SITE_RANKING, else a name match ([] for no match)"""
    if ranking in SITE_RANKING:
        return list(SITE_RANKING[ranking])
    group = char_group_by_name(ranking)
    return [group] if group else []


def _read_one(archive: zipfile.ZipFile, entry: zipfile.ZipInfo) -> pl.DataFrame:
    """One ranking CSV from the zip, typed, with our column names"""
    df = pl.read_csv(archive.read(entry), infer_schema=False)  # all text: typed below, column by column
    if set(df.columns) != set(COLUMNS):
        raise ValueError(f"{entry.filename}: columns {df.columns}, expected {list(COLUMNS)} (did the format change?)")
    df = df.rename(COLUMNS)
    return df.select(
        pl.lit(_ranking_name(entry)).alias("ranking"),
        pl.col("rank").cast(pl.Int32),
        pl.col("tag"),
        pl.col("player_id").cast(pl.Int64),
        pl.col("country").str.to_lowercase(),
        parse_rating(pl.col("rating")).alias("rating"),
        (pl.col("is_solo_main").str.to_lowercase() == "true").alias("is_solo_main"),
    )


def read_release(zip_path: Path) -> pl.DataFrame:
    """A downloaded release (its zip, read in place) as one table, one row per ranked player
    per pick: date (from the zip's month folder, see release_month), char_group_id, ranking
    (the source's name, eg 'Peach-Daisy'), rank, tag, player_id (start.gg), country, rating,
    is_solo_main.

    A ranking of several picks (an echo pair) is stored once per pick (see SITE_RANKING); one
    that matches none (Random, an unknown name) keeps a null char_group_id.
    """
    _, date = release_month(zip_path)
    with zipfile.ZipFile(zip_path) as archive:
        df = pl.concat([_read_one(archive, entry) for entry in _csv_entries(archive)])
    groups = {name: _groups(name) for name in df["ranking"].unique()}
    df = (
        df.with_columns(
            pl.col("ranking").replace_strict(groups, return_dtype=pl.List(pl.String)).alias("char_group_id")
        )
        .explode("char_group_id", empty_as_null=True)  # an empty list (Random) stays one row, with a null
        .with_columns(pl.lit(date, dtype=pl.Date).alias("date"), pl.col("char_group_id").cast(CHAR_GROUP_DTYPE))
    )
    first = ["date", "char_group_id", "ranking"]
    return df.select(first + [c for c in df.columns if c not in first]).sort(
        "char_group_id", "rank", nulls_last=True, maintain_order=True
    )


def unmatched_rankings(df: pl.DataFrame) -> list[str]:
    """Rankings that matched no pick and aren't known non-characters (eg a new or renamed one):
    add them to SITE_RANKING
    """
    unmatched = df.filter(pl.col("char_group_id").is_null())["ranking"].unique().to_list()
    return sorted(name for name in unmatched if name not in SITE_RANKING)


def merge_release(table: pl.DataFrame | None, release: pl.DataFrame) -> pl.DataFrame:
    """The table with `release`'s date replaced by it; other dates kept, newest first. `date`
    is a Date column in the result (a calendar day, no time).
    """
    release = release.with_columns(pl.col("date").cast(pl.Date))
    date = release["date"][0]
    if table is None or table.is_empty():
        return release
    kept = table.with_columns(pl.col("date").cast(pl.Date)).filter(pl.col("date") != date)
    return pl.concat([release, kept], how="diagonal_relaxed").sort("date", descending=True, maintain_order=True)
